-impl ImportTools {
-    /// The original import: [`ImportMode::Add`], holders taken.
-    pub fn new(world: &World, library: Vec<LibraryTool>) -> Result<Self, CommandError> {
-        Self::with_options(world, library, ImportMode::Add, true)
-    }
