-    /// `mode`, with the file's holders taken (#899's door).
-    pub fn with_mode(world: &World, library: Vec<LibraryTool>, mode: ImportMode) -> Result<Self, CommandError> {
-        Self::with_options(world, library, mode, true)
-    }
