-    /// [`ImportMode::Add`] with the holders choice (#889's door).
-    pub fn with_holders(world: &World, library: Vec<LibraryTool>, holders: bool) -> Result<Self, CommandError> {
-        Self::with_options(world, library, ImportMode::Add, holders)
-    }
